{
  "name": "@moozie/opencode-voice",
  "version": "0.0.2",
  "description": "Speech-to-text input plugin for OpenCode.",
  "license": "MIT",
  "author": "TheAmanM",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/TheAmanM/opencode-voice.git"
  },
  "homepage": "https://github.com/TheAmanM/opencode-voice#readme",
  "bugs": {
    "url": "https://github.com/TheAmanM/opencode-voice/issues"
  },
  "keywords": [
    "opencode",
    "speech-to-text",
    "voice-input",
    "whisper",
    "transcription",
    "tui"
  ],
  "type": "module",
  "publishConfig": {
    "access": "public",
    "tag": "latest",
    "provenance": true
  },
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./plugin": {
      "types": "./dist/plugin/index.d.ts",
      "import": "./dist/plugin/index.js"
    },
    "./tui": {
      "types": "./dist/plugin/tui.d.ts",
      "import": "./dist/plugin/tui.js"
    }
  },
  "engines": {
    "node": ">=22.22.2 <23",
    "opencode": ">=1.18.3 <2"
  },
  "scripts": {
    "clean": "node scripts/clean.mjs",
    "build": "node scripts/build.mjs",
    "build:local": "node scripts/build-local.mjs",
    "prepack": "npm run build",
    "prepublishOnly": "npm run verify:release",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "lint": "oxlint src scripts",
    "format": "prettier --write \"src/**/*.{ts,tsx}\" \"scripts/**/*.mjs\" \"docs/**/*.md\" \"package*.json\" \"tsconfig*.json\"",
    "format:check": "prettier --check \"src/**/*.{ts,tsx}\" \"scripts/**/*.mjs\" \"docs/**/*.md\" \"package*.json\" \"tsconfig*.json\"",
    "test": "node scripts/test.mjs",
    "coverage": "node scripts/test.mjs --coverage",
    "pack": "npm run verify:release",
    "validate:manifest": "node scripts/validate-manifest.mjs manifests/downloads.json",
    "verify:release": "node scripts/verify-release.mjs",
    "smoke:capture": "OPENCODE_VOICE_REAL_CAPTURE=1 npm test",
    "smoke:loader": "npm run build:local && python3 scripts/smoke-opencode-loader.py"
  },
  "files": [
    "dist",
    "manifests/downloads.json"
  ],
  "packageManager": "npm@11.15.0",
  "dependencies": {
    "pino": "^9.7.0",
    "tar": "^7.5.20"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.3 <2",
    "@opentui/solid": ">=0.4.3 <1",
    "solid-js": ">=1.9.12 <2"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.3",
    "@opentui/core": "0.4.3",
    "@opentui/solid": "0.4.3",
    "@types/node": "^24.0.3",
    "oxlint": "0.16.6",
    "prettier": "3.9.6",
    "solid-js": "1.9.12",
    "typescript": "^5.8.3"
  }
}
